LEVEL = 1
CFG = {1: ("amy", "read", "db1"), 2: ("amy", "write", "db1"), 3: ("bob", "delete", "db1")}
POLICY = {("amy", "read", "db1"), ("amy", "write", "db1")}
def pdp(sub, act, res):
    return (sub, act, res) in POLICY  # decision only
def pep(sub, act, res):
    decision = pdp(sub, act, res)     # enforcement only
    return "EXECUTED" if decision else "BLOCKED"
sub, act, res = CFG[LEVEL]
print("PDP decision:", pdp(sub, act, res), "| PEP:", pep(sub, act, res))

