LEVEL = 1
CFG = {1: 1, 2: 2, 3: 3}
POLICY_VERSION = CFG[LEVEL]
cache = {}
def check(sub, act):
    key = (sub, act, POLICY_VERSION)
    if key in cache:
        return cache[key] + " (cached)"
    decision = "ALLOW" if act == "read" else "DENY"
    cache[key] = decision
    return decision + " (fresh)"
print(check("amy", "read")); print(check("amy", "read"))
print("policy v%d: stale entries from older versions never hit" % POLICY_VERSION)

